<script setup lang="ts">
import type { Product } from '@ellas/shared';
const emit=defineEmits<{select:[product:Product]}>();
const props=withDefaults(defineProps<{label?:string;id?:string}>(),{label:'¿Qué necesita tu equipo?',id:'product-search'});
const query=ref('');const results=ref<Product[]>([]);const open=ref(false);const loading=ref(false);const failure=ref('');const active=ref(-1);let timer:ReturnType<typeof setTimeout>|undefined;let controller:AbortController|undefined;let sequence=0;
watch(query,()=>{clearTimeout(timer);controller?.abort();const request=++sequence;active.value=-1;failure.value='';if(query.value.trim().length<2){results.value=[];loading.value=false;return;}loading.value=true;open.value=true;timer=setTimeout(async()=>{controller=new AbortController();try{const data=await $fetch<{products:Product[]}>('/api/catalog/suggestions',{query:{q:query.value.trim()},signal:controller.signal});if(request===sequence)results.value=data.products;}catch(error){if(request===sequence && (error as Error).name!=='AbortError')failure.value='No hemos podido buscar. Vuelve a escribir o abre el catálogo.';}finally{if(request===sequence)loading.value=false;}},200);});
function choose(product:Product){emit('select',product);open.value=false;query.value='';results.value=[];}
function blur(event:FocusEvent){if(!(event.currentTarget as HTMLElement).contains(event.relatedTarget as Node|null))open.value=false;}
function key(event:KeyboardEvent){if(event.key==='Escape')open.value=false;else if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();open.value=true;active.value=Math.max(0,Math.min(results.value.length-1,active.value+(event.key==='ArrowDown'?1:-1)));}else if(event.key==='Enter' && active.value>=0){event.preventDefault();const product=results.value[active.value];if(product)choose(product);}}
onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort();});
</script>
<template><div class="quick-search" @focusout="blur"><label :for="id">{{label}}</label><div class="quick-search-input"><AppIcon name="Search" :size="24"/><input :id="id" v-model="query" role="combobox" autocomplete="off" :aria-controls="id+'-results'" :aria-expanded="open && query.length>=2" aria-autocomplete="list" :aria-activedescendant="active>=0?id+'-option-'+active:undefined" placeholder="Busca una prenda o referencia. Ej. polo, JT150…" maxlength="100" @keydown="key" @focus="open=true"/><span v-if="loading" class="fine-print">Buscando…</span></div><div v-if="open && query.length>=2" class="quick-results"><p v-if="failure" role="alert">{{failure}}</p><p v-else-if="!loading && !results.length" role="status">No encontramos esa prenda. Prueba otra palabra.</p><ul :id="id+'-results'" role="listbox" :aria-label="props.label"><li v-for="(product,index) in results" :id="id+'-option-'+index" :key="product.reference" role="option" :aria-selected="index===active" @mousedown.prevent @mouseenter="active=index" @click="choose(product)"><img :src="product.imageSmall" :alt="product.name" width="48" height="60"/><span><b>{{product.name}}</b><small>{{product.reference}} · {{product.composition}}</small><small>{{product.weight?product.weight+' g/m²':'Gramaje no especificado'}} · {{product.colors.length}} colores</small></span><AppIcon name="ArrowRight" :size="18"/></li></ul><div v-if="active>=0 && results[active]" class="quick-result-compare"><span>{{results[active]?.reference}}</span><CompareButton :reference="results[active]!.reference"/></div><NuxtLink :to="{path:'/catalogo',query:{q:query}}" @mousedown.prevent>Ver todo el catálogo <AppIcon name="ArrowUpRight" :size="15"/></NuxtLink></div><p class="sr-only" role="status">{{!loading&&query.length>=2?results.length+' opciones encontradas':''}}</p></div></template>
